"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field

from .errors import RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week", "month": "month", "months": "month"}


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    until: dt.date = None
    times: int = None


def parse_duration(word):
    """'1h30m' -> 90. Returns None when the word is not a duration."""
    parts = re.findall(r"(\d+)([dhm])", word)
    if not parts or "".join(n + u for n, u in parts) != word:
        return None
    scale = {"d": 1440, "h": 60, "m": 1}
    total = sum(int(n) * scale[u] for n, u in parts)
    return total or None


def format_duration(minutes):
    hours, mins = divmod(minutes, 60)
    if hours and mins:
        return f"{hours}h{mins}m"
    return f"{hours}h" if hours else f"{mins}m"


def _time(word):
    hour, minute = word.split(":")
    return dt.time(int(hour), int(minute))


class _Words:
    def __init__(self, text):
        self.words = text.lower().split()
        self.pos = 0

    def peek(self):
        return self.words[self.pos] if self.pos < len(self.words) else None

    def take(self, what):
        word = self.peek()
        if word is None:
            raise RuleSyntaxError(f"expected {what}, found end of rule", self.pos)
        self.pos += 1
        return word

    def expect(self, keyword):
        if self.peek() != keyword:
            raise RuleSyntaxError(f"expected '{keyword}'", self.pos)
        self.pos += 1

    def convert(self, what, fn):
        at = self.pos
        word = self.take(what)
        try:
            value = fn(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            raise RuleSyntaxError(f"expected {what}, found {word!r}", at)
        return value


def parse_rule(text):
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() is not None and w.peek().isdigit():
        rule.every = w.convert("a count", lambda s: int(s) or None)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    if w.peek() == "on":
        w.take("on")
        if rule.unit == "month":
            rule.on = w.convert("month days", lambda s: [p if p == "last" else int(p) for p in s.split(",")])
        else:
            rule.on = w.convert("weekdays", lambda s: [WEEKDAYS.index(p) for p in s.split(",")])
    w.expect("at")
    rule.at = w.convert("times", lambda s: [_time(p) for p in s.split(",")])
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    rule.start = w.convert("a date", dt.date.fromisoformat)
    if w.peek() == "until":
        w.take("until")
        rule.until = w.convert("a date", dt.date.fromisoformat)
    elif w.peek() == "times":
        w.take("times")
        rule.times = w.convert("a count", lambda s: int(s) or None)
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    out = ["every"]
    if rule.every != 1:
        out.append(str(rule.every))
    out.append(rule.unit if rule.every == 1 else rule.unit + "s")
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    out += ["at", ",".join(t.strftime("%H:%M") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    out += ["from", rule.start.isoformat()]
    if rule.until:
        out += ["until", rule.until.isoformat()]
    if rule.times:
        out += ["times", str(rule.times)]
    return " ".join(out)
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass

ONE_DAY = dt.timedelta(days=1)


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: dt.datetime    # aware, in the rule's zone
    end: dt.datetime


def _months_between(a, b):
    return (b.year - a.year) * 12 + (b.month - a.month)


def _matches(rule, day):
    """Is `day` one of the rule's dates?"""
    if rule.unit == "day":
        return (day - rule.start).days % rule.every == 0
    if rule.unit == "week":
        weeks = (day - rule.start).days // 7
        return weeks % rule.every == 0 and day.weekday() in rule.on
    if _months_between(rule.start, day) % rule.every != 0:
        return False
    month_len = calendar.monthrange(day.year, day.month)[1]
    for item in rule.on:
        wanted = month_len if item == "last" else min(item, month_len)
        if day.day == wanted:
            return True
    return False


def expand(ruledef, not_after):
    """Yield the rule's occurrences in order, up to the local date `not_after`."""
    rule = ruledef.rule
    length = dt.timedelta(minutes=rule.minutes)
    day = rule.start
    while day <= not_after:
        if rule.until and day >= rule.until:
            break
        if _matches(rule, day):
            for time in rule.at:
                start = dt.datetime.combine(day, time, tzinfo=ruledef.tz)
                key = f"{day.isoformat()}T{time.strftime('%H:%M')}"
                yield Occurrence(ruledef, key, start, start + length)
        day += ONE_DAY

"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
from dataclasses import dataclass
from zoneinfo import ZoneInfo

from .errors import PlanError, RuleSyntaxError
from .rules import Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int


@dataclass
class Override:
    rule: str
    key: str
    action: str
    to: dt.datetime = None
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # (rule id, key) -> Override
    min_segment: int


def _zone(name):
    try:
        return ZoneInfo(name)
    except Exception:
        raise PlanError(f"unknown timezone {name!r}")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    rules = []
    for index, item in enumerate(raw.get("rules", [])):
        rid = item.get("id")
        if not rid:
            raise PlanError(f"rule #{index} has no id")
        try:
            rule = parse_rule(item["rule"])
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position)
        tz = _zone(item["timezone"]) if item.get("timezone") else default_tz
        rules.append(RuleDef(index, rid, rule, tz, item.get("priority", 0)))

    ids = {r.id for r in rules}
    overrides = {}
    for item in raw.get("overrides", []):
        rid, key, action = item.get("rule"), item.get("key"), item.get("action")
        if rid not in ids:
            raise PlanError(f"override for unknown rule {rid!r}")
        if action not in ("cancel", "move"):
            raise PlanError(f"rule {rid}: unknown override action {action!r}")
        ov = Override(rid, key, action)
        if action == "move":
            try:
                ov.to = dt.datetime.fromisoformat(item["to"])
            except (KeyError, ValueError, TypeError):
                raise PlanError(f"rule {rid}: move override needs a valid 'to'")
            if item.get("for"):
                ov.minutes = parse_duration(item["for"])
        overrides[(rid, key)] = ov

    min_segment = parse_duration(raw["min_segment"]) if raw.get("min_segment") else 0
    return Plan(rules, overrides, min_segment)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt

from .errors import PlanError
from .expand import expand
from .plan import load_plan


def _parse_bound(text, default_tz):
    try:
        value = dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
    except (ValueError, AttributeError):
        raise PlanError(f"invalid date-time {text!r}")
    if value.tzinfo is None:
        value = value.replace(tzinfo=default_tz)
    return value


def _collect(plan, start, end):
    found = []
    for ruledef in plan.rules:
        count = 0
        for occ in expand(ruledef, end.astimezone(ruledef.tz).date()):
            override = plan.overrides.get((ruledef.id, occ.key))
            if override and override.action == "cancel":
                continue
            count += 1
            if ruledef.rule.times and count > ruledef.rule.times:
                break
            if not (start <= occ.start < end):
                continue
            if override and override.action == "move":
                length = occ.end - occ.start
                if override.minutes:
                    length = dt.timedelta(minutes=override.minutes)
                occ.start = override.to.replace(tzinfo=ruledef.tz)
                occ.end = occ.start + length
            found.append(occ)
    return found


def _as_dict(occ):
    return {
        "rule": occ.rule.id,
        "key": occ.key,
        "start": occ.start.isoformat(timespec="seconds"),
        "end": occ.end.isoformat(timespec="seconds"),
    }


def occurrences(plan, start, end):
    plan_obj = load_plan(plan)
    default_tz = plan_obj.rules[0].tz if plan_obj.rules else dt.timezone.utc
    lo, hi = _parse_bound(start, default_tz), _parse_bound(end, default_tz)
    rows = [_as_dict(occ) for occ in _collect(plan_obj, lo, hi)]
    rows.sort(key=lambda row: (row["start"], row["end"]))
    return rows


